<?php
require_once __DIR__ . '/../database/database.php'; require_once __DIR__ . '/../app/auth.php'; require_once __DIR__ . '/../app/layout.php'; requireLogin();
$userId=$_SESSION['user_id'];$projectId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$projectId){header('Location: projects.php');exit;}$stmt=$pdo->prepare('SELECT id,name,description,status,created_at FROM projects WHERE id=? AND user_id=? LIMIT 1');$stmt->execute([$projectId,$userId]);$project=$stmt->fetch();if(!$project){header('Location: projects.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');if($title==='')$error='Goal title is required.';else{$stmt=$pdo->prepare("INSERT INTO goals (project_id,title,description,status) VALUES (?,?,?,'active')");$stmt->execute([$projectId,$title,$description?:null]);header('Location: project.php?id='.$projectId);exit;}}$stmt=$pdo->prepare('SELECT id,title,description,status,created_at,completed_at FROM goals WHERE project_id=? ORDER BY created_at DESC');$stmt->execute([$projectId]);$goals=$stmt->fetchAll();$total=count($goals);$completed=count(array_filter($goals,fn($g)=>in_array(strtolower($g['status']),['completed','complete','done'],true)));$progress=$total?round($completed/$total*100):0;$stmt=$pdo->prepare('SELECT id,next_step,remaining_work,ended_at FROM sessions WHERE project_id=? ORDER BY started_at DESC LIMIT 1');$stmt->execute([$projectId]);$latestSession=$stmt->fetch();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($project['name'])?> | Project Continuum</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><div class="app-shell"><?php renderSidebar('projects');?><main class="main-content"><a class="back-link" href="projects.php">← Back to Projects</a><header class="project-heading"><div><h1><?=htmlspecialchars($project['name'])?></h1><p class="metadata"><?=htmlspecialchars($project['description']?:'Keep your work context, progress, and next actions together.')?></p></div><div><a class="button" href="session_start.php?id=<?=(int)$projectId?>">▶ Start work session</a> <span class="badge <?=statusClass($project['status'])?>"><?=htmlspecialchars(statusLabel($project['status']))?></span></div></header><nav class="tabs"><a class="tab is-active" href="#overview">▣ Overview</a><a class="tab" href="#goals">✓ Goals</a><a class="tab" href="#new-goal">＋ Add goal</a></nav>
<section id="overview" class="overview-top"><div class="card overview-card"><h3>Progress Overview</h3><div class="donut" style="--degree:<?= $progress*3.6 ?>deg"><span><?= $progress ?>%<small>Overall Progress</small></span></div></div><div class="card overview-card"><h3>Project summary</h3><ul class="summary-list"><li>Total goals <strong><?= $total ?></strong></li><li>Completed <strong><?= $completed ?></strong></li><li>In progress <strong><?= $total-$completed ?></strong></li><li>Last updated <strong><?=date('M j',strtotime($project['created_at']))?></strong></li></ul></div><div class="card overview-card"><h3>Project timeline</h3><div class="timeline"><div>Project created</div><?php foreach(array_slice($goals,0,3) as $goal):?><div>Added: <?=htmlspecialchars($goal['title'])?></div><?php endforeach;?></div></div></section>
<section class="goals-notes"><div class="card panel" id="goals"><h2 class="panel-title">Goals</h2><?php if($goals):foreach($goals as $goal):$done=in_array(strtolower($goal['status']),['completed','complete','done'],true);?><div class="goal-item <?=$done?'done':''?>"><form method="post" action="goal_status.php"><input type="hidden" name="goal_id" value="<?= (int)$goal['id'] ?>"><input type="hidden" name="project_id" value="<?= (int)$projectId ?>"><button class="check" aria-label="Toggle goal completion" type="submit"></button></form><span><?=htmlspecialchars($goal['title'])?></span><span class="goal-status"><?=htmlspecialchars(statusLabel($goal['status']))?></span></div><?php endforeach;else:?><p class="empty">No goals yet—add the next step you want to remember.</p><?php endif;?></div><aside class="card panel"><h2 class="panel-title">Continuity note</h2><div class="note"><strong>Next step</strong><br><?=htmlspecialchars($latestSession['next_step']??'Start a work session and write your next concrete step.')?></div><?php if($latestSession && $latestSession['remaining_work']):?><div class="note"><strong>Unfinished</strong><br><?=htmlspecialchars($latestSession['remaining_work'])?></div><?php endif;?><a class="link-arrow" href="session_start.php?id=<?=(int)$projectId?>">Open work session →</a></aside></section>
<section class="card panel" id="new-goal" style="margin-top:16px"><h2 class="panel-title">Add a goal</h2><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><div class="field"><label for="title">Goal title</label><input id="title" name="title" maxlength="255" placeholder="What is the next concrete step?" required></div><div class="field"><label for="description">Description</label><input id="description" name="description" placeholder="Optional context for when you return"></div><button class="button" type="submit">Add Goal</button></form></section>
</main></div></body></html>
